-- Legacy allocations are generated by 0097 from these links and posted entries.
BEGIN;

CREATE TEMP TABLE rehearsal_receipt_matches ON COMMIT DROP AS
SELECT suffix, source,
       md5('nr-rehearsal:receipt-provenance:transaction:' || suffix)::uuid AS transaction_id,
       md5('nr-rehearsal:receipt-provenance:journal:' || suffix)::uuid AS journal_id,
       md5('nr-rehearsal:receipt-provenance:receipt:' || suffix)::uuid AS receipt_id,
       md5('nr-rehearsal:company:1')::uuid AS company_id,
       md5('nr-rehearsal:owner:1')::uuid AS owner_id,
       md5('nr-rehearsal:company:' || receipt_tenant)::uuid AS receipt_company_id,
       md5('nr-rehearsal:owner:' || receipt_tenant)::uuid AS receipt_owner_id,
       amount
  FROM (VALUES ('bank-created', 'bank_reconciliation', 1, 24.50),
               ('receipt-owned', 'receipt', 1, 34.50),
               ('foreign-receipt', 'bank_reconciliation', 2, 44.50))
       cases(suffix, source, receipt_tenant, amount);

INSERT INTO journal_entries (id, company_id, date, memo, created_by, entry_number, status,
                             source, source_id, posted_by, posted_at, created_at)
SELECT journal_id, company_id, '2026-03-15', 'Receipt payment ' || suffix, owner_id,
       'JE-RECEIPT-' || suffix, 'posted', source,
       CASE WHEN source = 'receipt' THEN receipt_id ELSE transaction_id END,
       owner_id, '2026-03-15', '2026-03-15'
  FROM rehearsal_receipt_matches;

INSERT INTO journal_lines (entry_id, account_id, debit, credit)
SELECT journal_id, md5('nr-rehearsal:account:' || company_id || ':' || code)::uuid,
       CASE WHEN code = '5000' THEN amount ELSE 0 END,
       CASE WHEN code = '1020' THEN amount ELSE 0 END
  FROM rehearsal_receipt_matches CROSS JOIN (VALUES ('5000'), ('1020')) accounts(code);

INSERT INTO receipts (id, company_id, merchant, "date", amount, vat_amount, currency, uploaded_by,
                      posted, journal_entry_id, created_at)
SELECT receipt_id, receipt_company_id, 'Synthetic supplier ' || suffix, '2026-03-15',
       amount, 0, 'AED', receipt_owner_id, source = 'receipt',
       CASE WHEN source = 'receipt' THEN journal_id END, '2026-03-15'
  FROM rehearsal_receipt_matches;

INSERT INTO bank_transactions (id, company_id, bank_statement_account_id, bank_account_id,
                               transaction_date, description, amount, reference, import_source,
                               is_reconciled, match_status, matched_receipt_id,
                               matched_journal_entry_id, created_at)
SELECT transaction_id, company_id, md5('nr-rehearsal:bank-account:1')::uuid,
       md5('nr-rehearsal:account:' || company_id || ':1020')::uuid,
       '2026-03-15', 'Statement receipt ' || suffix, -amount, 'RECEIPT-' || suffix,
       'csv:rehearsal-receipt-provenance', true, 'matched', receipt_id, journal_id, '2026-03-15'
  FROM rehearsal_receipt_matches;

-- An imported, already-reconciled local line can still hold foreign summary
-- pointers. Preserve the historical row and distinguish its ownership findings.
INSERT INTO bank_transactions (id, company_id, bank_statement_account_id, bank_account_id,
                               transaction_date, description, amount, reference, import_source,
                               is_reconciled, match_status, matched_invoice_id,
                               matched_journal_entry_id, created_at)
SELECT md5('nr-rehearsal:bank-competing-claim:foreign-line')::uuid,
       md5('nr-rehearsal:company:1')::uuid, md5('nr-rehearsal:bank-account:1')::uuid,
       foreign_line.bank_account_id, '2026-03-19', 'Imported foreign allocation reference',
       foreign_line.amount, 'REVIEW-FOREIGN-CLAIM', 'csv:rehearsal-competing-claim',
       true, 'matched', foreign_line.matched_invoice_id, foreign_line.matched_journal_entry_id,
       '2026-03-19'
  FROM bank_transactions foreign_line
 WHERE foreign_line.id = md5('nr-rehearsal:bank-line:2:1')::uuid;

COMMIT;
